mapper.select:
SELECT
FROM t_quartz_task t LEFT JOIN sys_datasource_config ds ON ds.id = t.datasource_id where 1=1
AND t.id = #{queryDTO.id}
AND ( INSTR(t.task_name, #{queryDTO.taskName}) OR INSTR(t.remark, #{queryDTO.taskName}) )
AND t.task_status = #{queryDTO.taskStatus}
AND t.task_type = #{queryDTO.taskType}
AND INSTR(t.task_system,#{queryDTO.taskSystem})
AND INSTR(t.theme,#{queryDTO.theme})
order by t.id desc

mapper.update:
UPDATE t_quartz_task t
set t.job_key = #{taskEntity.jobKey}
WHERE t.id = #{taskEntity.id}

UPDATE t_quartz_task t
set t.task_status = #{taskStatus}
WHERE t.id = #{taskId}

mapper.select:
SELECT DISTINCT pre_task_id
FROM t_quartz_task_dependency
WHERE task_id = #{taskId}
  AND dependency_type = #{dependencyType}
ORDER BY pre_task_id

SELECT DISTINCT task_id
FROM t_quartz_task_dependency
WHERE pre_task_id = #{preTaskId}
  AND dependency_type = #{dependencyType}
ORDER BY task_id

mapper.delete:
DELETE FROM t_quartz_task_dependency
WHERE task_id = #{taskId}
  AND dependency_type = #{dependencyType}
